using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

var topic = args.Length > 0 ? string.Join(" ", args) : "the impact of quantum computing on cryptography";

Console.WriteLine($"Research Agent Starting...");
Console.WriteLine($"Topic: {topic}");
Console.WriteLine(new string('-', 50));

// Configure the AI chat client with tool support
var openAiClient = new OpenAIClient(Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "your-api-key");
IChatClient chatClient = openAiClient
    .GetChatClient("gpt-4o")
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// Create the research tools
var researchTools = new ResearchTools();
var chatOptions = new ChatOptions
{
    Tools = [
        AIFunctionFactory.Create(researchTools.SearchWeb),
        AIFunctionFactory.Create(researchTools.TakeNote),
        AIFunctionFactory.Create(researchTools.GetNotes),
    ]
};

// Run the agent loop
var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a given topic thoroughly.

        Instructions:
        1. Use the SearchWeb tool to find information about the topic (perform multiple searches with different queries)
        2. Use the TakeNote tool to save important findings as you go
        3. After gathering enough information, use GetNotes to review all your notes
        4. Finally, provide a comprehensive summary of your research findings

        Be thorough - search for different aspects of the topic and take detailed notes.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

Console.WriteLine("\nAgent is researching...\n");

var response = await chatClient.GetResponseAsync(messages, chatOptions);

Console.WriteLine("\n" + new string('=', 50));
Console.WriteLine("RESEARCH SUMMARY");
Console.WriteLine(new string('=', 50));
Console.WriteLine(response.Text);
Console.WriteLine(new string('=', 50));

Console.WriteLine($"\nNotes collected: {researchTools.NoteCount}");

// --- Tool Definitions ---

public class ResearchTools
{
    private readonly List<string> _notes = [];

    public int NoteCount => _notes.Count;

    [Description("Search the web for information on a query. Returns search results with titles and snippets.")]
    public string SearchWeb([Description("The search query")] string query)
    {
        Console.WriteLine($"  [Tool] Searching web: \"{query}\"");

        // Simulated web search results for demonstration
        return $"""
            Search results for: "{query}"

            1. Title: Overview of {query}
               Snippet: Recent developments in {query} have shown significant progress. 
               Experts suggest this area will continue to evolve rapidly in the coming years.
               URL: https://example.com/article1

            2. Title: {query} - Latest Research
               Snippet: A comprehensive study published in 2025 examines the current state 
               of {query}, highlighting key breakthroughs and remaining challenges.
               URL: https://example.com/article2

            3. Title: Future Implications of {query}
               Snippet: Industry analysts predict that {query} will transform multiple sectors, 
               with applications ranging from healthcare to finance.
               URL: https://example.com/article3
            """;
    }

    [Description("Take a note to remember an important finding during research.")]
    public string TakeNote(
        [Description("The note content to save")] string content,
        [Description("A short label for the note")] string label)
    {
        _notes.Add($"[{label}] {content}");
        Console.WriteLine($"  [Tool] Note saved: \"{label}\"");
        return $"Note saved successfully: [{label}]";
    }

    [Description("Retrieve all notes taken during the research session.")]
    public string GetNotes()
    {
        Console.WriteLine("  [Tool] Retrieving all notes...");
        if (_notes.Count == 0)
            return "No notes have been taken yet.";

        return "Research Notes:\n" + string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }
}

